<?= view('components/page_start', ['pageTitle' => $pageTitle]) ?>
<?php $hasUnread = count(array_filter($notifications, static fn(array $item): bool => empty($item['read_at']))) > 0; ?>
<section class="page-section"><div class="container-xl"><div class="d-flex justify-content-between align-items-end mb-5"><div><p class="eyebrow">Account</p><h1 class="section-title mb-0">Notifications</h1></div><?php if ($hasUnread): ?><form action="/notifications/read-all" method="post"><button class="btn btn-outline-brand btn-sm">Mark all as read</button></form><?php endif; ?></div><div class="surface-card overflow-hidden"><?php if ($notifications === []): ?><div class="empty-state"><div><i class="fa-regular fa-bell mb-3"></i><h2 class="h4">No notifications yet</h2><p class="text-muted-brand mb-0">Order updates will appear here.</p></div></div><?php endif; ?><?php foreach($notifications as $notification): ?><form action="/notifications/read/<?= esc($notification['id']) ?>" method="post"><button class="notification-item notification-button p-4 w-100 text-start <?= empty($notification['read_at']) ? 'notification-item-unread' : '' ?>" type="submit"><span class="notification-title"><?= esc($notification['title']) ?></span><span class="notification-message mt-1"><?= esc($notification['message']) ?></span><small class="d-block mt-2 text-muted-brand"><?= esc(date('M j, Y g:i A', strtotime($notification['created_at']))) ?></small></button></form><?php endforeach;?></div></div></section>
<?= view('components/page_end') ?>
